import { useEffect, useMemo, useState } from 'react';
import * as XLSX from 'xlsx';
import { useManagerShellNavigation } from '../ManagerShell';
import { useTenantQuery } from '../../hooks/useTenantQuery';
import { enterpriseGroupsService, type ManagerReportsModuleResponse } from '../../services/enterprise-groups.service';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Input } from '../ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { BarChart3, CalendarDays, ChevronLeft, ChevronRight, Download, FileBarChart, LayoutDashboard, LayoutGrid, List, Loader2, RefreshCw, Search, Users } from 'lucide-react';
import { cn } from '../ui/utils';
import { useCardsOnlyBelowTableBreakpoint } from '../ui/ViewLayoutSelect';
import { MANAGER_REPORTS_VIEWS, type ManagerReportsView } from './manager-reports.types';

type BranchOption = { id: string; name: string; businessUnitId?: string | null };
type LayoutMode = 'table' | 'cards';
const numberFormat = new Intl.NumberFormat('es-NI', { maximumFractionDigits: 2 });
const formatNumber = (value: unknown) => numberFormat.format(Number(value || 0));
const formatMoney = (value: unknown, currency = 'NIO') => `${currency} ${formatNumber(value)}`;
const formatDate = (value: unknown) => { if (!value) return '—'; const date = new Date(String(value)); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleDateString('es-NI'); };
const statusLabel = (value: unknown) => String(value || '—').replaceAll('_', ' ');
const labels = Object.fromEntries(MANAGER_REPORTS_VIEWS.map((item) => [item.id, item.label])) as Record<ManagerReportsView, string>;

export function ManagerReportsModule({ view, onViewChange, groupId, businessUnitId, branchId, branches }: { view: ManagerReportsView; onViewChange: (view: ManagerReportsView) => void; groupId: string; businessUnitId?: string; branchId?: string; branches: BranchOption[] }) {
  const { sidebarCollapsed } = useManagerShellNavigation();
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [status, setStatus] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [layoutMode, setLayoutMode] = useState<LayoutMode>('table');
  const isCompactTableViewport = useCardsOnlyBelowTableBreakpoint();
  const effectiveLayoutMode: LayoutMode = isCompactTableViewport ? 'cards' : layoutMode;
  const [exporting, setExporting] = useState(false);
  const query = useTenantQuery<ManagerReportsModuleResponse>(
    ['manager-reports-module', groupId, view, businessUnitId || 'all', branchId || 'all', debouncedSearch, status, dateFrom, dateTo, page, pageSize],
    (signal) => enterpriseGroupsService.getReportsModule(groupId, { view, businessUnitId, branchId, search: debouncedSearch || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, page, pageSize }, signal),
    { enabled: Boolean(groupId) },
  );
  const response = query.data;
  const rows = response?.data || [];
  const metrics = response?.metrics || {};
  const showBranch = !branchId && branches.length > 1;
  useEffect(() => { const timer = window.setTimeout(() => setDebouncedSearch(search), 300); return () => window.clearTimeout(timer); }, [search]);
  const changeView = (next: ManagerReportsView) => { setPage(1); setSearch(''); setStatus(''); setDateFrom(''); setDateTo(''); onViewChange(next); };
  const exportReport = async () => {
    setExporting(true);
    try {
      const report = await enterpriseGroupsService.getReportsModule(groupId, { view, businessUnitId, branchId, search: search || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, page: 1, pageSize: 5000, report: true });
      const exportRows = (report.data || []).map((row: any) => ({ Vista: labels[view], Registro: row.number || row.name || row.productName || row.employeeName || row.id, Fecha: formatDate(row.date || row.createdAt || row.periodEnd), Estado: statusLabel(row.status || row.kind), Monto: row.total ?? row.amount ?? row.balance ?? row.netPay ?? '', Sucursal: row.branchName || '', Rubro: row.businessUnitName || '' }));
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(exportRows.length ? exportRows : [{ Mensaje: 'Sin registros para el alcance seleccionado' }]), 'Reportes');
      XLSX.writeFile(workbook, `manager-reportes-${view}.xlsx`);
    } finally { setExporting(false); }
  };
  const Icon = useMemo(() => view === 'overview' ? LayoutDashboard : FileBarChart, [view]);
  return <div className="manager-reports-module min-w-0 space-y-5 overflow-x-hidden p-4 sm:p-6 md:p-8">
    <div className="flex min-w-0 flex-col gap-4 md:flex-row md:items-start md:justify-between">
      <div className="flex min-w-0 items-start gap-3"><div className="flex size-12 shrink-0 items-center justify-center rounded-2xl bg-primary/10 text-primary"><Icon className="size-6" /></div><div className="min-w-0"><h1 className="truncate text-3xl font-black uppercase italic tracking-tighter sm:text-4xl">Reportes <span className="text-primary">consolidados</span></h1><Badge variant="outline" className="mt-3 border-primary/20 bg-primary/10 text-[10px] font-black uppercase tracking-widest text-primary">{branches.length} sucursal(es) en el alcance</Badge></div></div>
      <div className="flex shrink-0 flex-wrap gap-2"><Button variant="outline" className="rounded-xl" onClick={() => void query.refetch()} disabled={query.isFetching}><RefreshCw className={cn('mr-2 size-4', query.isFetching && 'animate-spin')} />Actualizar</Button><Button variant="outline" className="rounded-xl" onClick={() => void exportReport()} disabled={exporting}>{exporting ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Download className="mr-2 size-4" />}Exportar Excel</Button></div>
    </div>
    {sidebarCollapsed && <div className="manager-module-subnav flex min-w-0 gap-2 overflow-x-auto rounded-2xl border border-border/60 bg-muted/30 p-1.5">{MANAGER_REPORTS_VIEWS.map((item) => <button key={item.id} type="button" onClick={() => changeView(item.id)} className={cn('flex-none rounded-xl px-3 py-2 text-[11px] font-black uppercase tracking-wide text-muted-foreground transition-colors hover:bg-card hover:text-foreground', view === item.id && 'bg-primary text-primary-foreground shadow-sm')}><span className="sm:hidden">{item.label.slice(0, 3)}</span><span className="hidden sm:inline">{item.label}</span></button>)}</div>}
    {view === 'overview' ? <ReportsOverview metrics={metrics} /> : <><ReportsFilters search={search} setSearch={(value) => { setSearch(value); setPage(1); }} status={status} setStatus={(value) => { setStatus(value); setPage(1); }} dateFrom={dateFrom} setDateFrom={(value) => { setDateFrom(value); setPage(1); }} dateTo={dateTo} setDateTo={(value) => { setDateTo(value); setPage(1); }} layoutMode={effectiveLayoutMode} setLayoutMode={setLayoutMode} /><ReportsKpis view={view} metrics={metrics} />{query.isLoading ? <LoadingState /> : query.error ? <EmptyState title="No se pudo cargar el reporte" description="Verifica el permiso Manager de Reportes y vuelve a actualizar." /> : effectiveLayoutMode === 'cards' ? <ReportsCards view={view} rows={rows} showBranch={showBranch} /> : <ReportsTable view={view} rows={rows} showBranch={showBranch} />}<Pagination page={response?.meta.page || page} totalPages={response?.meta.totalPages || 1} total={response?.meta.total || 0} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={(value) => { setPageSize(value); setPage(1); }} /></>}
  </div>;
}

function ReportsOverview({ metrics }: { metrics: Record<string, any> }) { const cards = [['Ventas', metrics.sales], ['Compras', metrics.purchases], ['Movimientos financieros', metrics.financial], ['Líneas de inventario', metrics.inventoryLines], ['Unidades en inventario', metrics.inventoryUnits], ['Clientes', metrics.customers], ['Proveedores', metrics.providers], ['Empleados', metrics.employees], ['Suscripciones', metrics.subscriptions]] as const; return <div className="space-y-5"><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <Card key={label} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="flex items-center gap-4 p-5"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><BarChart3 className="size-5" /></div><div className="min-w-0"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-1 truncate text-2xl font-black tracking-tight">{formatNumber(value)}</p></div></CardContent></Card>)}</div><Card className="rounded-3xl border-primary/20 bg-primary/5"><CardHeader><CardTitle className="text-lg font-black uppercase italic tracking-tight">Lectura gerencial</CardTitle></CardHeader><CardContent className="grid grid-cols-1 gap-4 text-sm md:grid-cols-3"><div><p className="text-muted-foreground">Registros operativos</p><p className="mt-1 font-black">{formatNumber(Number(metrics.sales || 0) + Number(metrics.purchases || 0) + Number(metrics.financial || 0))}</p></div><div><p className="text-muted-foreground">Cobertura del alcance</p><p className="mt-1 font-black">{formatNumber(metrics.branchCount)} sucursal(es)</p></div><div><p className="text-muted-foreground">Uso recomendado</p><p className="mt-1 font-semibold text-muted-foreground">Filtra por rubro y sucursal para comparar resultados sin mezclar operaciones.</p></div></CardContent></Card></div>; }
function ReportsFilters({ search, setSearch, status, setStatus, dateFrom, setDateFrom, dateTo, setDateTo, layoutMode, setLayoutMode }: { search: string; setSearch: (value: string) => void; status: string; setStatus: (value: string) => void; dateFrom: string; setDateFrom: (value: string) => void; dateTo: string; setDateTo: (value: string) => void; layoutMode: LayoutMode; setLayoutMode: (value: LayoutMode) => void }) { return <Card className="rounded-3xl border-border/60 shadow-sm"><CardContent className="grid min-w-0 grid-cols-1 gap-3 p-4 md:grid-cols-2 xl:grid-cols-[minmax(220px,1.4fr)_minmax(150px,0.7fr)_minmax(150px,0.7fr)_auto] xl:items-end"><label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>Buscar</span><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Número, nombre, descripción..." className="pl-9" /></div></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Estado</span><select value={status} onChange={(event) => setStatus(event.target.value)} className="h-10 w-full rounded-xl border border-border bg-background px-3 text-sm font-normal"><option value="">Todos</option><option value="ACTIVE">Activo</option><option value="PAID">Pagado</option><option value="PENDING">Pendiente</option><option value="COMPLETED">Completado</option><option value="CANCELLED">Cancelado</option></select></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha desde</span><Input type="date" value={dateFrom} onChange={(event) => setDateFrom(event.target.value)} /></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha hasta</span><Input type="date" value={dateTo} onChange={(event) => setDateTo(event.target.value)} /></label><div className="flex items-center justify-end gap-1 rounded-xl border border-border/60 bg-muted/20 p-1"><Button type="button" variant={layoutMode === 'table' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('table')} aria-label="Vista tabla"><List className="size-4" /></Button><Button type="button" variant={layoutMode === 'cards' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('cards')} aria-label="Vista tarjetas"><LayoutGrid className="size-4" /></Button></div></CardContent></Card>; }
function ReportsKpis({ view, metrics }: { view: ManagerReportsView; metrics: Record<string, any> }) { const cards = view === 'sales' ? [['Registros', metrics.total], ['Facturado', formatMoney(metrics.amount)], ['Cobrado', formatMoney(metrics.paid)], ['Saldo', formatMoney(metrics.balance)]] : view === 'purchases' ? [['Registros', metrics.total], ['Comprado', formatMoney(metrics.amount)], ['Alcance', `${metrics.branchCount || 0} sucursal(es)`], ['Mayor actividad', metrics.topBranchName || 'Sin datos']] : view === 'financial' ? [['Registros', metrics.total], ['Ingresos', formatMoney(metrics.income)], ['Gastos', formatMoney(metrics.expense)], ['Resultado', formatMoney(Number(metrics.income || 0) - Number(metrics.expense || 0))]] : view === 'inventory' ? [['Existencias', metrics.total], ['Unidades', formatNumber(metrics.units)], ['Disponibles', formatNumber(metrics.available)], ['Ubicaciones', metrics.locations]] : view === 'customers' ? [['Clientes', metrics.total], ['Activos', metrics.active], ['Saldo', formatMoney(metrics.balance)], ['Sucursales', metrics.branchCount]] : view === 'providers' ? [['Proveedores', metrics.total], ['Activos', metrics.active], ['Saldo', formatMoney(metrics.balance)], ['Sucursales', metrics.branchCount]] : view === 'subscriptions' ? [['Registros', metrics.total], ['Activas', metrics.active], ['Pendientes', metrics.pending], ['Valor', formatMoney(metrics.amount)]] : [['Registros', metrics.total], ['Sucursales', metrics.branchCount], ['Información', 'Solo lectura'], ['Orden', 'Más reciente']]; return <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <div key={String(label)} className="rounded-2xl border border-border/60 bg-card p-4 shadow-sm"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-2 truncate text-xl font-black">{typeof value === 'number' ? formatNumber(value) : value || '0'}</p></div>)}</div>; }
function ReportsTable({ view, rows, showBranch }: { view: ManagerReportsView; rows: any[]; showBranch: boolean }) { const columns = reportColumns(view, showBranch); return <Card className="overflow-hidden rounded-3xl border-border/60 shadow-sm"><CardHeader className="border-b border-border/60"><CardTitle className="text-lg font-black uppercase italic tracking-tight">{labels[view]}</CardTitle><p className="text-sm text-muted-foreground">Datos informativos ordenados de lo más reciente a lo más antiguo.</p></CardHeader><CardContent className="p-0">{rows.length ? <div className="sales-responsive-table overflow-x-auto"><Table className="min-w-[920px]"><TableHeader><TableRow>{columns.map((column) => <TableHead key={column.label}>{column.label}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((row) => <TableRow key={row.id}>{columns.map((column) => <TableCell key={`${row.id}-${column.label}`} className={cn('max-w-64', column.numeric && 'text-right font-semibold')}>{column.render(row)}</TableCell>)}</TableRow>)}</TableBody></Table></div> : <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />}</CardContent></Card>; }
function reportColumns(view: ManagerReportsView, showBranch: boolean) { const branch = { label: 'Sucursal', render: (row: any) => <span className="font-semibold text-primary">{row.branchName || 'Sucursal'}</span> }; const date = { label: 'Fecha', render: (row: any) => formatDate(row.date || row.createdAt || row.periodEnd) }; let columns: Array<{ label: string; numeric?: boolean; render: (row: any) => React.ReactNode }> = []; if (view === 'sales') columns = [{ label: 'Factura', render: (row) => row.number || '—' }, { label: 'Cliente', render: (row) => row.customerName || '—' }, date, { label: 'Estado', render: (row) => <Badge variant="outline" className="capitalize">{statusLabel(row.status)}</Badge> }, { label: 'Total', numeric: true, render: (row) => formatMoney(row.total, row.currency) }]; else if (view === 'purchases') columns = [{ label: 'Orden', render: (row) => row.number || '—' }, { label: 'Proveedor', render: (row) => row.supplierName || '—' }, date, { label: 'Estado', render: (row) => <Badge variant="outline" className="capitalize">{statusLabel(row.status)}</Badge> }, { label: 'Total', numeric: true, render: (row) => formatMoney(row.total, row.currency) }]; else if (view === 'financial') columns = [{ label: 'Registro', render: (row) => row.number || '—' }, { label: 'Tipo', render: (row) => <Badge variant="outline">{row.kind || '—'}</Badge> }, date, { label: 'Categoría', render: (row) => row.category || '—' }, { label: 'Monto', numeric: true, render: (row) => formatMoney(row.amount, row.currency) }]; else if (view === 'inventory') columns = [{ label: 'Código', render: (row) => <span className="font-mono font-semibold">{row.productCode || '—'}</span> }, { label: 'Producto', render: (row) => row.productName || '—' }, { label: 'Ubicación', render: (row) => row.warehouseName || '—' }, { label: 'Stock', numeric: true, render: (row) => formatNumber(row.quantity) }, { label: 'Disponible', numeric: true, render: (row) => formatNumber(row.available) }]; else if (view === 'customers' || view === 'providers') columns = [{ label: 'Código', render: (row) => row.code || '—' }, { label: view === 'customers' ? 'Cliente' : 'Proveedor', render: (row) => row.name || '—' }, { label: 'Tipo', render: (row) => row.type || '—' }, { label: 'Identificación', render: (row) => row.ruc || row.taxId || '—' }, { label: 'Saldo', numeric: true, render: (row) => formatMoney(row.balance) }]; else if (view === 'subscriptions') columns = [{ label: 'Módulo', render: (row) => row.module || '—' }, { label: 'Tipo', render: (row) => row.kind || '—' }, date, { label: 'Estado', render: (row) => <Badge variant="outline" className="capitalize">{statusLabel(row.status || (row.isActive ? 'ACTIVE' : 'INACTIVE'))}</Badge> }, { label: 'Valor', numeric: true, render: (row) => formatMoney(row.price) }]; else columns = [{ label: 'Registro', render: (row) => row.employeeName || row.number || row.name || '—' }, date, { label: 'Estado', render: (row) => statusLabel(row.status) }, { label: 'Monto', numeric: true, render: (row) => formatMoney(row.netPay ?? row.amount ?? row.total) }]; return showBranch ? [...columns, branch] : columns; }
function ReportsCards({ view, rows, showBranch }: { view: ManagerReportsView; rows: any[]; showBranch: boolean }) { if (!rows.length) return <EmptyState title="Sin registros" description="No hay información para el alcance seleccionado." />; return <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map((row) => <Card key={row.id} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="space-y-3 p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-base font-black">{row.number || row.employeeName || row.productName || row.name || row.id}</p><p className="text-xs text-muted-foreground">{row.customerName || row.supplierName || row.category || labels[view]}</p></div>{row.status && <Badge variant="outline" className="shrink-0 capitalize">{statusLabel(row.status)}</Badge>}</div><div className="grid grid-cols-2 gap-2 text-sm"><div><p className="text-xs text-muted-foreground">Fecha</p><p className="font-semibold">{formatDate(row.date || row.createdAt || row.periodEnd)}</p></div><div><p className="text-xs text-muted-foreground">Valor</p><p className="font-black">{formatMoney(row.total ?? row.amount ?? row.balance ?? row.quantity)}</p></div></div>{showBranch && <p className="border-t border-border/60 pt-2 text-xs font-semibold text-primary">{row.branchName || 'Sucursal'}</p>}</CardContent></Card>)}</div>; }
function Pagination({ page, totalPages, total, pageSize, onPageChange, onPageSizeChange }: { page: number; totalPages: number; total: number; pageSize: number; onPageChange: (page: number) => void; onPageSizeChange: (size: number) => void }) { return <div className="flex flex-col gap-3 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between"><span>{formatNumber(total)} registro(s)</span><div className="flex items-center gap-2"><select value={pageSize} onChange={(event) => onPageSizeChange(Number(event.target.value))} className="h-9 rounded-lg border border-border bg-background px-2 text-xs"><option value={25}>25 / página</option><option value={50}>50 / página</option><option value={100}>100 / página</option></select><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.max(1, page - 1))} disabled={page <= 1} aria-label="Página anterior"><ChevronLeft className="size-4" /></Button><span className="min-w-20 text-center text-xs font-semibold">Página {page} de {totalPages}</span><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.min(totalPages, page + 1))} disabled={page >= totalPages} aria-label="Página siguiente"><ChevronRight className="size-4" /></Button></div></div>; }
function LoadingState() { return <div className="flex min-h-48 items-center justify-center text-sm text-muted-foreground"><RefreshCw className="mr-2 size-5 animate-spin" />Cargando reportes consolidados...</div>; }
function EmptyState({ title, description }: { title: string; description: string }) { return <div className="flex min-h-48 flex-col items-center justify-center rounded-3xl border border-dashed border-border px-5 text-center"><Users className="size-8 text-muted-foreground/40" /><p className="mt-3 font-black">{title}</p><p className="mt-1 text-sm text-muted-foreground">{description}</p></div>; }
