import { useEffect, useMemo, useState, type ReactNode } from 'react';
import * as XLSX from 'xlsx';
import { useManagerShellNavigation } from '../ManagerShell';
import { useTenantQuery } from '../../hooks/useTenantQuery';
import { enterpriseGroupsService, type ManagerFinanceModuleResponse } from '../../services/enterprise-groups.service';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Input } from '../ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { Banknote, BarChart3, CalendarDays, ChevronLeft, ChevronRight, Download, LayoutDashboard, LayoutGrid, Landmark, List, Loader2, RefreshCw, Search, TrendingDown, TrendingUp, Wallet } from 'lucide-react';
import { cn } from '../ui/utils';
import { useCardsOnlyBelowTableBreakpoint } from '../ui/ViewLayoutSelect';
import { MANAGER_FINANCE_VIEWS, type ManagerFinanceView } from './manager-finance.types';

type BranchOption = { id: string; name: string; businessUnitId?: string | null };
type LayoutMode = 'table' | 'cards';
type Column = { label: string; numeric?: boolean; render: (row: any) => ReactNode };

const numberFormat = new Intl.NumberFormat('es-NI', { maximumFractionDigits: 2 });
const formatNumber = (value: unknown) => numberFormat.format(Number(value || 0));
const formatMoney = (value: unknown, currency = 'NIO') => `${currency} ${formatNumber(value)}`;
const formatDate = (value: unknown) => {
  if (!value) return '—';
  const date = new Date(String(value));
  return Number.isNaN(date.getTime()) ? '—' : date.toLocaleDateString('es-NI');
};
const statusLabel = (value: unknown) => ({ ACTIVE: 'Activo', INACTIVE: 'Inactivo', OPEN: 'Abierto', CLOSED: 'Cerrado', PENDING: 'Pendiente', PAID: 'Pagado', PARTIAL: 'Parcial', CANCELLED: 'Cancelado', APPROVED: 'Aprobado', DRAFT: 'Borrador', IN: 'Entrada', OUT: 'Salida', DEBIT: 'Débito', CREDIT: 'Crédito' } as Record<string, string>)[String(value || '').toUpperCase()] || String(value || '—').replaceAll('_', ' ');
const labels = Object.fromEntries(MANAGER_FINANCE_VIEWS.map((item) => [item.id, item.label])) as Record<ManagerFinanceView, string>;

const icons: Record<ManagerFinanceView, typeof BarChart3> = {
  overview: LayoutDashboard, cash: Landmark, receivables: TrendingUp, payables: TrendingDown,
  income: TrendingUp, expenses: Wallet, recurring: RefreshCw, calendar: CalendarDays,
  analysis: BarChart3, balance: Landmark, losses: TrendingDown,
};

export function ManagerFinanceModule({ view, onViewChange, groupId, businessUnitId, branchId, branches, reportCurrency }: { view: ManagerFinanceView; onViewChange: (view: ManagerFinanceView) => void; groupId: string; businessUnitId?: string; branchId?: string; branches: BranchOption[]; reportCurrency: string }) {
  const { sidebarCollapsed } = useManagerShellNavigation();
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [status, setStatus] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [layoutMode, setLayoutMode] = useState<LayoutMode>('table');
  const isCompactTableViewport = useCardsOnlyBelowTableBreakpoint();
  const effectiveLayoutMode: LayoutMode = isCompactTableViewport ? 'cards' : layoutMode;
  const [exporting, setExporting] = useState(false);
  const query = useTenantQuery<ManagerFinanceModuleResponse>(
    ['manager-finance', groupId, view, businessUnitId || 'all', branchId || 'all', debouncedSearch, status, dateFrom, dateTo, reportCurrency, page, pageSize],
    (signal) => enterpriseGroupsService.getFinanceModule(groupId, { view, businessUnitId, branchId, search: debouncedSearch || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, reportCurrency, page, pageSize }, signal),
    { enabled: Boolean(groupId) },
  );
  const response = query.data;
  const rows = response?.data || [];
  const metrics = response?.metrics || {};
  const showBranch = !branchId && branches.length > 1;

  useEffect(() => { const timer = window.setTimeout(() => setDebouncedSearch(search), 300); return () => window.clearTimeout(timer); }, [search]);
  const changeView = (next: ManagerFinanceView) => { setPage(1); setSearch(''); setStatus(''); setDateFrom(''); setDateTo(''); onViewChange(next); };
  const exportReport = async () => {
    setExporting(true);
    try {
      const report = await enterpriseGroupsService.getFinanceModule(groupId, { view, businessUnitId, branchId, search: search || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, reportCurrency, page: 1, pageSize: 5000, report: true });
      const workbook = XLSX.utils.book_new();
      const exportRows = (report.data || []).map((row: any) => {
        const original = row.amount ?? row.total ?? row.balance ?? (view === 'analysis' ? row.net : undefined);
        const equivalent = row.reportAmount ?? row.reportTotal ?? row.reportBalance ?? (view === 'analysis' ? row.net : undefined);
        return { Vista: labels[view], Identificador: row.number || row.name || row.id, Fecha: formatDate(row.date || row.createdAt || row.nextExecutionDate), Descripción: row.description || row.source || row.category || '', Estado: statusLabel(row.status), Monto: formatMoney(original, row.currency || (view === 'analysis' ? reportCurrency : 'NIO')), Equivalencia: equivalent == null ? '' : formatMoney(equivalent, reportCurrency), 'Tasa aplicada': row.reportRateLabel || '', Sucursal: row.branchName || '', Rubro: row.businessUnitName || '' };
      });
      XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(exportRows.length ? exportRows : [{ Mensaje: 'Sin registros para el alcance seleccionado' }]), 'Finanzas');
      XLSX.writeFile(workbook, `manager-finanzas-${view}.xlsx`);
    } finally { setExporting(false); }
  };
  const Icon = icons[view];
  return <div className="finance-module min-w-0 space-y-5 overflow-x-hidden p-4 sm:p-6 md:p-8">
    <div className="flex min-w-0 flex-col gap-4 md:flex-row md:items-start md:justify-between">
      <div className="flex min-w-0 items-start gap-3"><div className="flex size-12 shrink-0 items-center justify-center rounded-2xl bg-primary/10 text-primary"><Icon className="size-6" /></div><div className="min-w-0"><h1 className="truncate text-3xl font-black uppercase italic tracking-tighter sm:text-4xl">Finanzas <span className="text-primary">consolidadas</span></h1><Badge variant="outline" className="mt-3 border-primary/20 bg-primary/10 text-[10px] font-black uppercase tracking-widest text-primary">{branches.length} sucursal(es) en el alcance</Badge></div></div>
      <div className="flex shrink-0 flex-wrap gap-2"><Button variant="outline" className="rounded-xl" onClick={() => void query.refetch()} disabled={query.isFetching}><RefreshCw className={cn('mr-2 size-4', query.isFetching && 'animate-spin')} />Actualizar</Button><Button variant="outline" className="rounded-xl" onClick={() => void exportReport()} disabled={exporting}>{exporting ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Download className="mr-2 size-4" />}Exportar Excel</Button></div>
    </div>
    {sidebarCollapsed && <div className="manager-module-subnav flex min-w-0 gap-2 overflow-x-auto rounded-2xl border border-border/60 bg-muted/30 p-1.5">{MANAGER_FINANCE_VIEWS.map((item) => <button key={item.id} type="button" onClick={() => changeView(item.id)} className={cn('flex-none rounded-xl px-3 py-2 text-[11px] font-black uppercase tracking-wide text-muted-foreground transition-colors hover:bg-card hover:text-foreground', view === item.id && 'bg-primary text-primary-foreground shadow-sm')}><span className="sm:hidden">{item.label.slice(0, 3)}</span><span className="hidden sm:inline">{item.label}</span></button>)}</div>}
    {view === 'overview' ? <FinanceOverview metrics={metrics} reportCurrency={reportCurrency} /> : <><FinanceFilters view={view} search={search} setSearch={(value) => { setSearch(value); setPage(1); }} status={status} setStatus={(value) => { setStatus(value); setPage(1); }} dateFrom={dateFrom} setDateFrom={(value) => { setDateFrom(value); setPage(1); }} dateTo={dateTo} setDateTo={(value) => { setDateTo(value); setPage(1); }} layoutMode={effectiveLayoutMode} setLayoutMode={setLayoutMode} /><FinanceKpis view={view} metrics={metrics} reportCurrency={reportCurrency} />{query.isLoading ? <LoadingState /> : query.error ? <EmptyState title="No se pudo cargar la vista" description="Verifica el permiso Manager de Finanzas y vuelve a actualizar." /> : effectiveLayoutMode === 'cards' ? <FinanceCards view={view} rows={rows} showBranch={showBranch} reportCurrency={reportCurrency} /> : <FinanceTable view={view} rows={rows} showBranch={showBranch} reportCurrency={reportCurrency} />}<Pagination page={response?.meta.page || page} totalPages={response?.meta.totalPages || 1} total={response?.meta.total || 0} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={(value) => { setPageSize(value); setPage(1); }} /></>}
  </div>;
}

function FinanceMoney({ row, field = 'amount', reportCurrency }: { row: any; field?: string; reportCurrency: string }) { const original = row[field] ?? (field === 'amount' ? row.total ?? row.balance : undefined); const equivalent = field === 'total' ? row.reportTotal : field === 'balance' ? row.reportBalance : row.reportAmount; return <div className="min-w-[126px]"><p className="font-black tabular-nums">{formatMoney(original, row.currency || 'NIO')}</p>{equivalent != null && <p className="text-[10px] font-bold tabular-nums text-primary">≈ {formatMoney(equivalent, reportCurrency)}</p>}{row.reportRateLabel && <p className="mt-0.5 text-[9px] font-semibold leading-3 text-muted-foreground">{row.reportRateLabel}{row.reportRateEffectiveAt ? ` · ${formatDate(row.reportRateEffectiveAt)}` : ''}</p>}</div>; }
function FinanceOverview({ metrics, reportCurrency }: { metrics: Record<string, any>; reportCurrency: string }) { const cards = [['Ingresos', formatMoney(metrics.income, metrics.amountCurrency || reportCurrency), TrendingUp, 'text-primary bg-primary/10'], ['Gastos', formatMoney(metrics.expense, metrics.amountCurrency || reportCurrency), TrendingDown, 'text-primary bg-primary/10'], ['Resultado neto', formatMoney(metrics.net, metrics.amountCurrency || reportCurrency), BarChart3, 'text-primary bg-primary/10'], ['Cuentas bancarias', metrics.bankAccounts, Landmark, 'text-primary bg-primary/10'], ['Cuentas por cobrar', formatMoney(metrics.receivables, metrics.amountCurrency || reportCurrency), TrendingUp, 'text-primary bg-primary/10'], ['Cuentas por pagar', formatMoney(metrics.payables, metrics.amountCurrency || reportCurrency), TrendingDown, 'text-primary bg-primary/10'], ['Ingresos registrados', metrics.incomeRecords, Banknote, 'text-primary bg-primary/10'], ['Gastos registrados', metrics.expenseRecords, Wallet, 'text-primary bg-primary/10']] as const; return <div className="space-y-5"><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value, CardIcon, tone]) => <Card key={label} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="flex items-center gap-4 p-5"><div className={cn('flex size-11 shrink-0 items-center justify-center rounded-xl', tone)}><CardIcon className="size-5" /></div><div className="min-w-0"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-1 truncate text-2xl font-black tracking-tight">{typeof value === 'number' ? formatNumber(value) : value || '0'}</p></div></CardContent></Card>)}</div><Card className="rounded-3xl border-primary/20 bg-primary/5"><CardHeader><CardTitle className="text-lg font-black uppercase italic tracking-tight">Lectura financiera</CardTitle></CardHeader><CardContent className="grid grid-cols-1 gap-4 text-sm md:grid-cols-4"><div><p className="text-muted-foreground">Sucursal con mayor ingreso</p><p className="mt-1 font-black">{metrics.topIncomeBranchName || 'Sin datos'}</p></div><div><p className="text-muted-foreground">Sucursal con mayor gasto</p><p className="mt-1 font-black">{metrics.topExpenseBranchName || 'Sin datos'}</p></div><div><p className="text-muted-foreground">Moneda del reporte</p><p className="mt-1 font-black text-primary">{reportCurrency}</p></div><div><p className="text-muted-foreground">Valoración</p><p className="mt-1 font-semibold text-muted-foreground">{metrics.valuationLabel || 'Se conserva la valoración histórica disponible.'}</p></div></CardContent></Card></div>; }

function FinanceFilters({ view: _view, search, setSearch, status, setStatus, dateFrom, setDateFrom, dateTo, setDateTo, layoutMode, setLayoutMode }: { view: ManagerFinanceView; search: string; setSearch: (value: string) => void; status: string; setStatus: (value: string) => void; dateFrom: string; setDateFrom: (value: string) => void; dateTo: string; setDateTo: (value: string) => void; layoutMode: LayoutMode; setLayoutMode: (value: LayoutMode) => void }) { return <Card className="rounded-3xl border-border/60 shadow-sm"><CardContent className="grid min-w-0 grid-cols-1 gap-3 p-4 md:grid-cols-2 xl:grid-cols-[minmax(220px,1.4fr)_minmax(150px,0.7fr)_minmax(150px,0.7fr)_auto] xl:items-end"><label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>Buscar</span><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Número, descripción, cuenta..." className="pl-9" /></div></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Estado</span><select value={status} onChange={(event) => setStatus(event.target.value)} className="h-10 w-full rounded-xl border border-border bg-background px-3 text-sm font-normal"><option value="">Todos</option><option value="ACTIVE">Activo</option><option value="OPEN">Abierto</option><option value="CLOSED">Cerrado</option><option value="PENDING">Pendiente</option><option value="PAID">Pagado</option></select></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha desde</span><div className="relative"><CalendarDays className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input type="date" value={dateFrom} onChange={(event) => setDateFrom(event.target.value)} className="pl-9" /></div></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha hasta</span><div className="relative"><CalendarDays className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input type="date" value={dateTo} onChange={(event) => setDateTo(event.target.value)} className="pl-9" /></div></label><div className="flex items-center justify-end gap-1 rounded-xl border border-border/60 bg-muted/20 p-1"><Button type="button" variant={layoutMode === 'table' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('table')} aria-label="Vista tabla"><List className="size-4" /></Button><Button type="button" variant={layoutMode === 'cards' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('cards')} aria-label="Vista tarjetas"><LayoutGrid className="size-4" /></Button></div></CardContent></Card>; }

function FinanceKpis({ view, metrics, reportCurrency }: { view: ManagerFinanceView; metrics: Record<string, any>; reportCurrency: string }) { const currency = metrics.amountCurrency || reportCurrency; const cards = useMemo(() => { if (view === 'cash') return [['Cuentas bancarias', metrics.bankAccounts], ['Entradas', formatMoney(metrics.inflow, currency)], ['Salidas', formatMoney(metrics.outflow, currency)], ['Saldo neto', formatMoney(metrics.net, currency)]]; if (view === 'receivables') return [['Cuentas', metrics.total], ['Facturado', formatMoney(metrics.amount, currency)], ['Cobrado', formatMoney(metrics.paid, currency)], ['Saldo', formatMoney(metrics.balance, currency)]]; if (view === 'payables') return [['Cuentas', metrics.total], ['Facturado', formatMoney(metrics.amount, currency)], ['Pagado', formatMoney(metrics.paid, currency)], ['Saldo', formatMoney(metrics.balance, currency)]]; return [['Registros', metrics.total], ['Monto', formatMoney(metrics.amount, currency)], ['Sucursal principal', metrics.topBranchName || 'Sin datos'], ['Alcance', `${metrics.branchCount || 0} sucursal(es)`]]; }, [currency, metrics, view]); return <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <div key={String(label)} className="rounded-2xl border border-border/60 bg-card p-4 shadow-sm"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-2 truncate text-xl font-black">{typeof value === 'number' ? formatNumber(value) : value || '0'}</p></div>)}</div>; }

function FinanceTable({ view, rows, showBranch, reportCurrency }: { view: ManagerFinanceView; rows: any[]; showBranch: boolean; reportCurrency: string }) { const columns = tableColumns(view, showBranch, reportCurrency); return <Card className="overflow-hidden rounded-3xl border-border/60 shadow-sm"><CardHeader className="border-b border-border/60"><CardTitle className="text-lg font-black uppercase italic tracking-tight">{labels[view]}</CardTitle><p className="text-sm text-muted-foreground">Ordenado de lo más reciente a lo más antiguo. Los datos son de solo lectura.</p></CardHeader><CardContent className="p-0">{rows.length ? <div className="sales-responsive-table overflow-x-auto"><Table className="min-w-[980px]"><TableHeader><TableRow>{columns.map((column) => <TableHead key={column.label}>{column.label}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((row) => <TableRow key={row.id}>{columns.map((column) => <TableCell key={`${row.id}-${column.label}`} className={cn('max-w-64', column.numeric && 'text-right font-semibold')}>{column.render(row)}</TableCell>)}</TableRow>)}</TableBody></Table></div> : <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />}</CardContent></Card>; }
function FinanceCards({ view, rows, showBranch, reportCurrency }: { view: ManagerFinanceView; rows: any[]; showBranch: boolean; reportCurrency: string }) { if (!rows.length) return <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />; return <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map((row) => <Card key={row.id} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="space-y-3 p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-base font-black">{row.number || row.name || row.code || row.id?.slice(0, 8)}</p><p className="text-xs text-muted-foreground">{row.description || row.category || labels[view]}</p></div>{row.status && <Badge variant="outline" className="shrink-0 capitalize">{statusLabel(row.status)}</Badge>}</div><div className="grid grid-cols-2 gap-2 text-sm"><div><p className="text-xs text-muted-foreground">Fecha</p><p className="font-semibold">{formatDate(row.date || row.createdAt || row.nextExecutionDate)}</p></div><div><p className="text-xs text-muted-foreground">Monto</p><FinanceMoney row={row} reportCurrency={reportCurrency} /></div></div>{showBranch && <p className="border-t border-border/60 pt-2 text-xs font-semibold text-primary">{row.branchName || 'Sucursal'}</p>}</CardContent></Card>)}</div>; }

function tableColumns(view: ManagerFinanceView, showBranch: boolean, reportCurrency: string): Column[] { const branch = { label: 'Sucursal', render: (row: any) => <span className="font-semibold text-primary">{row.branchName || 'Sucursal'}</span> }; const money = (row: any, field = 'amount') => <FinanceMoney row={row} field={field} reportCurrency={reportCurrency} />; const common: Column[] = [{ label: 'Registro', render: (row) => <span className="font-semibold">{row.number || row.name || row.code || '—'}</span> }, { label: 'Fecha', render: (row) => formatDate(row.date || row.createdAt || row.nextExecutionDate) }, { label: 'Descripción', render: (row) => row.description || row.source || row.category || '—' }, { label: 'Estado', render: (row) => <Badge variant="outline" className="capitalize">{statusLabel(row.status)}</Badge> }, { label: 'Monto', numeric: true, render: (row) => money(row) }]; const byView: Partial<Record<ManagerFinanceView, Column[]>> = { cash: [{ label: 'Cuenta', render: (row) => <span className="font-semibold">{row.bankName || row.name || row.accountName || '—'}</span> }, { label: 'Fecha', render: (row) => formatDate(row.date) }, { label: 'Tipo', render: (row) => statusLabel(row.direction || row.accountType) }, { label: 'Referencia', render: (row) => row.reference || row.description || '—' }, { label: 'Monto', numeric: true, render: (row) => money(row) }], balance: [{ label: 'Código', render: (row) => <span className="font-mono font-semibold text-primary">{row.code}</span> }, { label: 'Cuenta', render: (row) => row.name }, { label: 'Tipo', render: (row) => statusLabel(row.type) }, { label: 'Saldo', numeric: true, render: (row) => money(row, 'balance') }], analysis: [{ label: 'Categoría', render: (row) => row.category || row.name || '—' }, { label: 'Ingresos', numeric: true, render: (row) => formatMoney(row.income, reportCurrency) }, { label: 'Gastos', numeric: true, render: (row) => formatMoney(row.expense, reportCurrency) }, { label: 'Neto', numeric: true, render: (row) => formatMoney(row.net, reportCurrency) }], calendar: [{ label: 'Concepto', render: (row) => row.description || row.source || '—' }, { label: 'Próxima fecha', render: (row) => formatDate(row.nextExecutionDate || row.date) }, { label: 'Frecuencia', render: (row) => statusLabel(row.frequency) }, { label: 'Monto', numeric: true, render: (row) => money(row) }], receivables: [{ label: 'Factura', render: (row) => row.number }, { label: 'Fecha', render: (row) => formatDate(row.date) }, { label: 'Vencimiento', render: (row) => formatDate(row.dueDate) }, { label: 'Total', numeric: true, render: (row) => money(row, 'total') }, { label: 'Saldo', numeric: true, render: (row) => money(row, 'balance') }], payables: [{ label: 'Factura', render: (row) => row.number }, { label: 'Fecha', render: (row) => formatDate(row.date) }, { label: 'Vencimiento', render: (row) => formatDate(row.dueDate) }, { label: 'Total', numeric: true, render: (row) => money(row, 'total') }, { label: 'Saldo', numeric: true, render: (row) => money(row, 'balance') }], }; const columns = byView[view] || common; return showBranch ? [...columns, branch] : columns; }
function Pagination({ page, totalPages, total, pageSize, onPageChange, onPageSizeChange }: { page: number; totalPages: number; total: number; pageSize: number; onPageChange: (page: number) => void; onPageSizeChange: (size: number) => void }) { return <div className="flex flex-col gap-3 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between"><span>{formatNumber(total)} registro(s)</span><div className="flex items-center gap-2"><select value={pageSize} onChange={(event) => onPageSizeChange(Number(event.target.value))} className="h-9 rounded-lg border border-border bg-background px-2 text-xs"><option value={25}>25 / página</option><option value={50}>50 / página</option><option value={100}>100 / página</option></select><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.max(1, page - 1))} disabled={page <= 1}><ChevronLeft className="size-4" /></Button><span className="min-w-20 text-center text-xs font-semibold">Página {page} de {totalPages}</span><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.min(totalPages, page + 1))} disabled={page >= totalPages}><ChevronRight className="size-4" /></Button></div></div>; }
function LoadingState() { return <div className="flex min-h-48 items-center justify-center text-sm text-muted-foreground"><RefreshCw className="mr-2 size-5 animate-spin" />Cargando finanzas consolidadas...</div>; }
function EmptyState({ title, description }: { title: string; description: string }) { return <div className="rounded-3xl border border-dashed border-border p-10 text-center"><p className="font-black">{title}</p><p className="mt-1 text-sm text-muted-foreground">{description}</p></div>; }
