import { useEffect, useState, type ReactNode } from 'react';
import * as XLSX from 'xlsx';
import { useManagerShellNavigation } from '../ManagerShell';
import { useTenantQuery } from '../../hooks/useTenantQuery';
import { enterpriseGroupsService, type ManagerHrModuleResponse } from '../../services/enterprise-groups.service';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { Input } from '../ui/input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { BarChart3, CalendarDays, ChevronLeft, ChevronRight, Download, GraduationCap, LayoutDashboard, LayoutGrid, List, Loader2, RefreshCw, Search, ShieldCheck, Users, Wallet } from 'lucide-react';
import { cn } from '../ui/utils';
import { useCardsOnlyBelowTableBreakpoint } from '../ui/ViewLayoutSelect';
import { MANAGER_HR_VIEWS, type ManagerHrView } from './manager-hr.types';

type BranchOption = { id: string; name: string; businessUnitId?: string | null };
type LayoutMode = 'table' | 'cards';
const numberFormat = new Intl.NumberFormat('es-NI', { maximumFractionDigits: 2 });
const formatNumber = (value: unknown) => numberFormat.format(Number(value || 0));
const formatMoney = (value: unknown, currency = 'NIO') => `${currency} ${formatNumber(value)}`;
const formatDate = (value: unknown) => { if (!value) return '—'; const date = new Date(String(value)); return Number.isNaN(date.getTime()) ? '—' : date.toLocaleDateString('es-NI'); };
const statusLabel = (value: unknown) => String(value || '—').replaceAll('_', ' ');
const labels = Object.fromEntries(MANAGER_HR_VIEWS.map((item) => [item.id, item.label])) as Record<ManagerHrView, string>;

export function ManagerHRModule({ view, onViewChange, groupId, businessUnitId, branchId, branches }: { view: ManagerHrView; onViewChange: (view: ManagerHrView) => void; groupId: string; businessUnitId?: string; branchId?: string; branches: BranchOption[] }) {
  const { sidebarCollapsed } = useManagerShellNavigation();
  const [search, setSearch] = useState('');
  const [debouncedSearch, setDebouncedSearch] = useState('');
  const [status, setStatus] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [layoutMode, setLayoutMode] = useState<LayoutMode>('table');
  const isCompactTableViewport = useCardsOnlyBelowTableBreakpoint();
  const effectiveLayoutMode: LayoutMode = isCompactTableViewport ? 'cards' : layoutMode;
  const [exporting, setExporting] = useState(false);
  const query = useTenantQuery<ManagerHrModuleResponse>(
    ['manager-hr-module', groupId, view, businessUnitId || 'all', branchId || 'all', debouncedSearch, status, dateFrom, dateTo, page, pageSize],
    (signal) => enterpriseGroupsService.getHrModule(groupId, { view, businessUnitId, branchId, search: debouncedSearch || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, page, pageSize }, signal),
    { enabled: Boolean(groupId) },
  );
  const response = query.data;
  const rows = response?.data || [];
  const metrics = response?.metrics || {};
  const showBranch = !branchId && branches.length > 1;
  useEffect(() => { const timer = window.setTimeout(() => setDebouncedSearch(search), 300); return () => window.clearTimeout(timer); }, [search]);
  const changeView = (next: ManagerHrView) => { setPage(1); setSearch(''); setStatus(''); setDateFrom(''); setDateTo(''); onViewChange(next); };
  const exportReport = async () => {
    setExporting(true);
    try {
      const report = await enterpriseGroupsService.getHrModule(groupId, { view, businessUnitId, branchId, search: search || undefined, status: status || undefined, dateFrom: dateFrom || undefined, dateTo: dateTo || undefined, page: 1, pageSize: 5000, report: true });
      const exportRows = (report.data || []).map((row: any) => ({ Vista: labels[view], Registro: row.employeeName || row.name || row.employeeNumber || row.id, Fecha: formatDate(row.date || row.createdAt || row.periodEnd || row.startDate), Estado: statusLabel(row.status || row.employmentStatus || row.paymentStatus), Valor: row.netPay ?? row.amount ?? row.salary ?? row.cost ?? row.days ?? '', Sucursal: row.branchName || '', Rubro: row.businessUnitName || '' }));
      const workbook = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(exportRows.length ? exportRows : [{ Mensaje: 'Sin registros para el alcance seleccionado' }]), 'Recursos Humanos');
      XLSX.writeFile(workbook, `manager-recursos-humanos-${view}.xlsx`);
    } finally { setExporting(false); }
  };
  return <div className="manager-hr-module min-w-0 space-y-5 overflow-x-hidden p-4 sm:p-6 md:p-8">
    <div className="flex min-w-0 flex-col gap-4 md:flex-row md:items-start md:justify-between"><div className="flex min-w-0 items-start gap-3"><div className="flex size-12 shrink-0 items-center justify-center rounded-2xl bg-primary/10 text-primary"><Users className="size-6" /></div><div className="min-w-0"><h1 className="truncate text-3xl font-black uppercase italic tracking-tighter sm:text-4xl">Recursos <span className="text-primary">Humanos</span></h1><Badge variant="outline" className="mt-3 border-primary/20 bg-primary/10 text-[10px] font-black uppercase tracking-widest text-primary">{branches.length} sucursal(es) en el alcance</Badge></div></div><div className="flex shrink-0 flex-wrap gap-2"><Button variant="outline" className="rounded-xl" onClick={() => void query.refetch()} disabled={query.isFetching}><RefreshCw className={cn('mr-2 size-4', query.isFetching && 'animate-spin')} />Actualizar</Button><Button variant="outline" className="rounded-xl" onClick={() => void exportReport()} disabled={exporting}>{exporting ? <Loader2 className="mr-2 size-4 animate-spin" /> : <Download className="mr-2 size-4" />}Exportar Excel</Button></div></div>
    {sidebarCollapsed && <div className="manager-module-subnav flex min-w-0 gap-2 overflow-x-auto rounded-2xl border border-border/60 bg-muted/30 p-1.5">{MANAGER_HR_VIEWS.map((item) => <button key={item.id} type="button" onClick={() => changeView(item.id)} className={cn('flex-none rounded-xl px-3 py-2 text-[11px] font-black uppercase tracking-wide text-muted-foreground transition-colors hover:bg-card hover:text-foreground', view === item.id && 'bg-primary text-primary-foreground shadow-sm')}><span className="sm:hidden">{item.label.slice(0, 3)}</span><span className="hidden sm:inline">{item.label}</span></button>)}</div>}
    {view === 'overview' ? <HROverview metrics={metrics} /> : <><HRFilters search={search} setSearch={(value) => { setSearch(value); setPage(1); }} status={status} setStatus={(value) => { setStatus(value); setPage(1); }} dateFrom={dateFrom} setDateFrom={(value) => { setDateFrom(value); setPage(1); }} dateTo={dateTo} setDateTo={(value) => { setDateTo(value); setPage(1); }} layoutMode={effectiveLayoutMode} setLayoutMode={setLayoutMode} /><HRKpis view={view} metrics={metrics} />{query.isLoading ? <LoadingState /> : query.error ? <EmptyState title="No se pudo cargar la vista" description="Verifica el permiso Manager de Recursos Humanos y vuelve a actualizar." /> : effectiveLayoutMode === 'cards' ? <HRCards view={view} rows={rows} showBranch={showBranch} /> : <HRTable view={view} rows={rows} showBranch={showBranch} />}<Pagination page={response?.meta.page || page} totalPages={response?.meta.totalPages || 1} total={response?.meta.total || 0} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={(value) => { setPageSize(value); setPage(1); }} /></>}
  </div>;
}

function HROverview({ metrics }: { metrics: Record<string, any> }) { const cards = [['Empleados', metrics.employees], ['Empleados activos', metrics.activeEmployees], ['Departamentos', metrics.departments], ['Nóminas', metrics.payroll], ['Monto neto', formatMoney(metrics.payrollAmount)], ['Asistencias', metrics.attendance], ['Permisos', metrics.leaves], ['Capacitaciones', metrics.trainings]] as const; return <div className="space-y-5"><div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <Card key={label} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="flex items-center gap-4 p-5"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><Users className="size-5" /></div><div className="min-w-0"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-1 truncate text-2xl font-black tracking-tight">{typeof value === 'string' ? value : formatNumber(value)}</p></div></CardContent></Card>)}</div><Card className="rounded-3xl border-primary/20 bg-primary/5"><CardHeader><CardTitle className="text-lg font-black uppercase italic tracking-tight">Lectura de talento</CardTitle></CardHeader><CardContent className="grid grid-cols-1 gap-4 text-sm md:grid-cols-3"><div><p className="text-muted-foreground">Cobertura activa</p><p className="mt-1 font-black">{formatNumber(metrics.activeEmployees)} de {formatNumber(metrics.employees)} empleados</p></div><div><p className="text-muted-foreground">Alcance</p><p className="mt-1 font-black">{formatNumber(metrics.branchCount)} sucursal(es)</p></div><div><p className="text-muted-foreground">Regla de lectura</p><p className="mt-1 font-semibold text-muted-foreground">La edición, aprobación y configuración permanecen dentro de la sucursal.</p></div></CardContent></Card></div>; }
function HRFilters({ search, setSearch, status, setStatus, dateFrom, setDateFrom, dateTo, setDateTo, layoutMode, setLayoutMode }: { search: string; setSearch: (value: string) => void; status: string; setStatus: (value: string) => void; dateFrom: string; setDateFrom: (value: string) => void; dateTo: string; setDateTo: (value: string) => void; layoutMode: LayoutMode; setLayoutMode: (value: LayoutMode) => void }) { return <Card className="rounded-3xl border-border/60 shadow-sm"><CardContent className="grid min-w-0 grid-cols-1 gap-3 p-4 md:grid-cols-2 xl:grid-cols-[minmax(220px,1.4fr)_minmax(150px,0.7fr)_minmax(150px,0.7fr)_auto] xl:items-end"><label className="min-w-0 space-y-1.5 text-xs font-bold text-muted-foreground"><span>Buscar</span><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" /><Input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Empleado, departamento, registro..." className="pl-9" /></div></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Estado</span><select value={status} onChange={(event) => setStatus(event.target.value)} className="erp-filter-select h-10 rounded-xl border border-border bg-background px-3 text-sm font-normal"><option value="">Todos</option><option value="ACTIVE">Activo</option><option value="PENDING">Pendiente</option><option value="PAID">Pagado</option><option value="COMPLETED">Completado</option><option value="ON_LEAVE">En permiso</option></select></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha desde</span><Input type="date" value={dateFrom} onChange={(event) => setDateFrom(event.target.value)} /></label><label className="space-y-1.5 text-xs font-bold text-muted-foreground"><span>Fecha hasta</span><Input type="date" value={dateTo} onChange={(event) => setDateTo(event.target.value)} /></label><div className="flex items-center justify-end gap-1 rounded-xl border border-border/60 bg-muted/20 p-1"><Button type="button" variant={layoutMode === 'table' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('table')} aria-label="Vista tabla"><List className="size-4" /></Button><Button type="button" variant={layoutMode === 'cards' ? 'secondary' : 'ghost'} size="icon" className="size-9 rounded-lg" onClick={() => setLayoutMode('cards')} aria-label="Vista tarjetas"><LayoutGrid className="size-4" /></Button></div></CardContent></Card>; }
function HRKpis({ view, metrics }: { view: ManagerHrView; metrics: Record<string, any> }) { const cards = view === 'employees' ? [['Empleados', metrics.total], ['Activos', metrics.active], ['Vendedores', metrics.sellers], ['Sucursales', metrics.branchCount]] : view === 'payroll' ? [['Nóminas', metrics.total], ['Neto', formatMoney(metrics.netPay)], ['Bruto', formatMoney(metrics.grossPay)], ['Pagadas', metrics.paid]] : view === 'attendance' ? [['Registros', metrics.total], ['Presentes', metrics.present], ['Horas', formatNumber(metrics.hours)], ['Sucursales', metrics.branchCount]] : view === 'leaves' ? [['Solicitudes', metrics.total], ['Días', formatNumber(metrics.days)], ['Pendientes', metrics.pending], ['Sucursales', metrics.branchCount]] : view === 'performance' || view === 'kpi' ? [['Evaluaciones', metrics.total], ['Promedio', formatNumber(metrics.average)], ['Completadas', metrics.completed], ['Sucursales', metrics.branchCount]] : view === 'training' ? [['Formaciones', metrics.trainings], ['Inscripciones', metrics.enrollments], ['Costo', formatMoney(metrics.cost)], ['Sucursales', metrics.branchCount]] : view === 'benefits' ? [['Beneficios', metrics.benefits], ['Empleados', metrics.employees], ['Costo', formatMoney(metrics.cost)], ['Sucursales', metrics.branchCount]] : view === 'departments' ? [['Departamentos', metrics.total], ['Empleados', metrics.employees], ['Activos', metrics.active], ['Sucursales', metrics.branchCount]] : [['Registros', metrics.total], ['Monto', formatMoney(metrics.amount)], ['Pagadas', metrics.paid], ['Sucursales', metrics.branchCount]]; return <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value]) => <div key={String(label)} className="rounded-2xl border border-border/60 bg-card p-4 shadow-sm"><p className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</p><p className="mt-2 truncate text-xl font-black">{typeof value === 'number' ? formatNumber(value) : value || '0'}</p></div>)}</div>; }
function HRTable({ view, rows, showBranch }: { view: ManagerHrView; rows: any[]; showBranch: boolean }) { const columns = hrColumns(view, showBranch); return <Card className="overflow-hidden rounded-3xl border-border/60 shadow-sm"><CardHeader className="border-b border-border/60"><CardTitle className="text-lg font-black uppercase italic tracking-tight">{labels[view]}</CardTitle><p className="text-sm text-muted-foreground">Consulta informativa ordenada por fecha y alcance.</p></CardHeader><CardContent className="p-0">{rows.length ? <div className="sales-responsive-table overflow-x-auto"><Table className="min-w-[980px]"><TableHeader><TableRow>{columns.map((column) => <TableHead key={column.label}>{column.label}</TableHead>)}</TableRow></TableHeader><TableBody>{rows.map((row) => <TableRow key={row.id}>{columns.map((column) => <TableCell key={`${row.id}-${column.label}`} className={cn('max-w-64', column.numeric && 'text-right font-semibold')}>{column.render(row)}</TableCell>)}</TableRow>)}</TableBody></Table></div> : <EmptyState title="Sin registros" description="No hay información para el rubro, sucursal y filtros seleccionados." />}</CardContent></Card>; }
function hrColumns(view: ManagerHrView, showBranch: boolean) { const branch = { label: 'Sucursal', render: (row: any) => <span className="font-semibold text-primary">{row.branchName || 'Sucursal'}</span> }; const date = { label: 'Fecha', render: (row: any) => formatDate(row.date || row.createdAt || row.periodEnd || row.startDate) }; let columns: Array<{ label: string; numeric?: boolean; render: (row: any) => ReactNode }> = []; if (view === 'employees') columns = [{ label: 'Empleado', render: (row) => <span className="font-semibold">{row.name || '—'}</span> }, { label: 'Código', render: (row) => row.employeeNumber || '—' }, { label: 'Departamento', render: (row) => row.departmentName || '—' }, { label: 'Puesto', render: (row) => row.positionName || '—' }, { label: 'Estado', render: (row) => statusLabel(row.employmentStatus) }]; else if (view === 'departments') columns = [{ label: 'Código', render: (row) => row.code || '—' }, { label: 'Departamento', render: (row) => row.name || '—' }, { label: 'Empleados', numeric: true, render: (row) => formatNumber(row.employeeCount) }, { label: 'Puestos', numeric: true, render: (row) => formatNumber(row.positionCount) }, { label: 'Estado', render: (row) => statusLabel(row.status) }]; else if (view === 'payroll') columns = [{ label: 'Empleado', render: (row) => row.employeeName || '—' }, { label: 'Período', render: (row) => `${formatDate(row.periodStart)} - ${formatDate(row.periodEnd)}` }, { label: 'Estado', render: (row) => statusLabel(row.status) }, { label: 'Pago', render: (row) => statusLabel(row.paymentStatus) }, { label: 'Neto', numeric: true, render: (row) => formatMoney(row.netPay, row.currency) }]; else if (view === 'attendance') columns = [{ label: 'Empleado', render: (row) => row.employeeName || '—' }, date, { label: 'Estado', render: (row) => statusLabel(row.status) }, { label: 'Horas', numeric: true, render: (row) => formatNumber(row.hoursWorked) }, { label: 'Horas extra', numeric: true, render: (row) => formatNumber(row.overtimeHours) }]; else if (view === 'leaves') columns = [{ label: 'Empleado', render: (row) => row.employeeName || '—' }, { label: 'Tipo', render: (row) => row.leaveTypeCustom || row.leaveType || '—' }, { label: 'Período', render: (row) => `${formatDate(row.startDate)} - ${formatDate(row.endDate)}` }, { label: 'Días', numeric: true, render: (row) => formatNumber(row.days) }, { label: 'Estado', render: (row) => statusLabel(row.status) }]; else if (view === 'training') columns = [{ label: 'Formación', render: (row) => row.title || '—' }, { label: 'Instructor', render: (row) => row.instructor || '—' }, date, { label: 'Inscritos', numeric: true, render: (row) => formatNumber(row.enrollmentCount) }, { label: 'Estado', render: (row) => statusLabel(row.status) }]; else if (view === 'benefits') columns = [{ label: 'Beneficio', render: (row) => row.name || '—' }, { label: 'Tipo', render: (row) => row.type || '—' }, { label: 'Proveedor', render: (row) => row.provider || '—' }, { label: 'Empleados', numeric: true, render: (row) => formatNumber(row.employeeCount) }, { label: 'Costo', numeric: true, render: (row) => formatMoney(row.cost, row.currency) }]; else if (view === 'commissions') columns = [{ label: 'Empleado', render: (row) => row.employeeName || '—' }, date, { label: 'Estado', render: (row) => statusLabel(row.status) }, { label: 'Tasa', numeric: true, render: (row) => `${formatNumber(row.rate)}%` }, { label: 'Monto', numeric: true, render: (row) => formatMoney(row.amount) }]; else columns = [{ label: 'Empleado', render: (row) => row.employeeName || '—' }, date, { label: 'Indicador', render: (row) => row.kpiDefinition?.name || row.rating || '—' }, { label: 'Resultado', numeric: true, render: (row) => formatNumber(row.actual ?? row.rating) }, { label: 'Estado', render: (row) => statusLabel(row.status) }]; return showBranch ? [...columns, branch] : columns; }
function HRCards({ view, rows, showBranch }: { view: ManagerHrView; rows: any[]; showBranch: boolean }) { if (!rows.length) return <EmptyState title="Sin registros" description="No hay información para el alcance seleccionado." />; return <div className="grid grid-cols-1 gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map((row) => <Card key={row.id} className="rounded-2xl border-border/60 shadow-sm"><CardContent className="space-y-3 p-5"><div className="flex items-start justify-between gap-3"><div className="min-w-0"><p className="truncate text-base font-black">{row.name || row.employeeName || row.title || row.employeeNumber || row.id}</p><p className="text-xs text-muted-foreground">{row.departmentName || row.positionName || row.type || labels[view]}</p></div>{(row.status || row.employmentStatus) && <Badge variant="outline" className="shrink-0 capitalize">{statusLabel(row.status || row.employmentStatus)}</Badge>}</div><div className="grid grid-cols-2 gap-2 text-sm"><div><p className="text-xs text-muted-foreground">Fecha</p><p className="font-semibold">{formatDate(row.date || row.createdAt || row.periodEnd || row.startDate)}</p></div><div><p className="text-xs text-muted-foreground">Valor</p><p className="font-black">{formatMoney(row.netPay ?? row.amount ?? row.salary ?? row.cost ?? row.days)}</p></div></div>{showBranch && <p className="border-t border-border/60 pt-2 text-xs font-semibold text-primary">{row.branchName || 'Sucursal'}</p>}</CardContent></Card>)}</div>; }
function Pagination({ page, totalPages, total, pageSize, onPageChange, onPageSizeChange }: { page: number; totalPages: number; total: number; pageSize: number; onPageChange: (page: number) => void; onPageSizeChange: (size: number) => void }) { return <div className="flex flex-col gap-3 text-sm text-muted-foreground sm:flex-row sm:items-center sm:justify-between"><span>{formatNumber(total)} registro(s)</span><div className="flex items-center gap-2"><select value={pageSize} onChange={(event) => onPageSizeChange(Number(event.target.value))} className="h-9 rounded-lg border border-border bg-background px-2 text-xs"><option value={25}>25 / página</option><option value={50}>50 / página</option><option value={100}>100 / página</option></select><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.max(1, page - 1))} disabled={page <= 1} aria-label="Página anterior"><ChevronLeft className="size-4" /></Button><span className="min-w-20 text-center text-xs font-semibold">Página {page} de {totalPages}</span><Button variant="outline" size="icon" className="size-9 rounded-lg" onClick={() => onPageChange(Math.min(totalPages, page + 1))} disabled={page >= totalPages} aria-label="Página siguiente"><ChevronRight className="size-4" /></Button></div></div>; }
function LoadingState() { return <div className="flex min-h-48 items-center justify-center text-sm text-muted-foreground"><RefreshCw className="mr-2 size-5 animate-spin" />Cargando Recursos Humanos consolidados...</div>; }
function EmptyState({ title, description }: { title: string; description: string }) { return <div className="flex min-h-48 flex-col items-center justify-center rounded-3xl border border-dashed border-border px-5 text-center"><GraduationCap className="size-8 text-muted-foreground/40" /><p className="mt-3 font-black">{title}</p><p className="mt-1 text-sm text-muted-foreground">{description}</p></div>; }
